sys_script_include.script:
function BusinessProcessGetMermaidSwimlanes(business_process,strDirection)
{
	if (BusinessProcessValidate(business_process,false) == false)
	{
		return false;
	}
	strDirection = GetStringValue(strDirection);
	if (strDirection == '')
	{
		strDirection = 'TD';
	}
	if (/^(TB|TD|BT|LR|RL)$/.test(strDirection) == false)
	{
		return false;
	}

	function GetMermaidLabel(strLabel,strId)
	{
		if (strLabel == '')
		{
			strLabel = strId;
		}
		var strLabel = strLabel.replace(/[\r\n\t]+/g,' ');
		strLabel = strLabel.replace(/["#&<>\[\]|\x60]/g,function(strCharacter)
			{
				return '#' + strCharacter.charCodeAt(0) + ';';
			});
		return '"' + strLabel + '"';
	}

	var aRoles = GetArrayValue(GetValue(business_process,'_roles'));
	var aStates = GetArrayValue(GetValue(business_process,'_states'));
	var aTransitions = GetArrayValue(GetValue(business_process,'_transitions'));
	var strInitialStateId = GetStringValue(GetValue(business_process,'initial_state'));
	var mapRoleLanes = {};
	var mapStateNodes = {};
	var mapTransitions = {};
	var mapNodeIds = {};
	var aLanes = [];

	function GetMermaidId(strId,strPrefix)
	{
		var strNodeId = strId.toLowerCase();
		strNodeId = strNodeId.replace(/[^a-z0-9_]+/g,'_');
		if (/^[a-z_]/.test(strNodeId) == false ||
			/^(end|subgraph|class|classdef|style|click|direction|linkstyle|acctitle|accdescr|graph|flowchart|default|call|interpolate)$/.test(strNodeId) == true)
		{
			strNodeId = strPrefix + strNodeId;
		}
		if (mapNodeIds['id_' + strNodeId] === true)
		{
			strNodeId = strPrefix + strNodeId;
		}
		var strBaseId = strNodeId;
		var nSuffix = 2;
		while (mapNodeIds['id_' + strNodeId] === true)
		{
			strNodeId = strBaseId + '_' + nSuffix;
			nSuffix++;
		}
		mapNodeIds['id_' + strNodeId] = true;
		return strNodeId;
	}

	for (var nRole = 0; nRole < aRoles.length; nRole++)
	{
		var role = aRoles[nRole];
		var strRoleId = GetStringValue(GetValue(role,'id'));
		var lane =
		{
			id: GetMermaidId('role_' + strRoleId,'role_'),
			name: GetStringValue(GetValue(role,'name')) || strRoleId,
			nodes: ''
		};
		mapRoleLanes['id_' + strRoleId] = lane;
		aLanes.push(lane);
	}

	var aOrderedStates = [];
	for (var nState = 0; nState < aStates.length; nState++)
	{
		var state = aStates[nState];
		var strStateId = GetStringValue(GetValue(state,'id'));
		var stateNode =
		{
			id: GetMermaidId(strStateId,'state_'),
			label: GetMermaidLabel(GetStringValue(GetValue(state,'name')),strStateId),
			transition_ids: GetArrayValue(GetValue(state,'_transitions')),
			lane: null,
			incoming_lane: null
		};
		var aStateRoleIds = GetArrayValue(GetValue(state,'_roles'));
		for (var nRole = 0; nRole < aStateRoleIds.length && !stateNode.lane; nRole++)
		{
			stateNode.lane = mapRoleLanes['id_' + GetStringValue(aStateRoleIds[nRole])];
		}
		mapStateNodes['id_' + strStateId] = stateNode;
		if (strStateId == strInitialStateId)
		{
			aOrderedStates.unshift(stateNode);
		}
		else
		{
			aOrderedStates.push(stateNode);
		}
	}

	for (var nTransition = 0; nTransition < aTransitions.length; nTransition++)
	{
		var transition = aTransitions[nTransition];
		var strTransitionId = GetStringValue(GetValue(transition,'id'));
		var strTargetStateId = GetStringValue(GetValue(transition,'target_state'));
		var stateTarget = mapStateNodes['id_' + strTargetStateId];
		if (!stateTarget)
		{
			continue;
		}

		var aTransitionRoleIds = GetArrayValue(GetValue(transition,'_roles'));
		var aTransitionLanes = [];
		for (var nRole = 0; nRole < aTransitionRoleIds.length; nRole++)
		{
			var lane = mapRoleLanes['id_' + GetStringValue(aTransitionRoleIds[nRole])];
			if (lane && aTransitionLanes.indexOf(lane) == -1)
			{
				aTransitionLanes.push(lane);
			}
		}
		mapTransitions['id_' + strTransitionId] =
		{
			id: strTransitionId,
			label: GetStringValue(GetValue(transition,'label')) || strTransitionId,
			target: stateTarget,
			lanes: aTransitionLanes
		};
	}

	for (var nState = 0; nState < aOrderedStates.length; nState++)
	{
		var stateNode = aOrderedStates[nState];
		for (var nTransition = 0; nTransition < stateNode.transition_ids.length; nTransition++)
		{
			var transition = mapTransitions['id_' + GetStringValue(stateNode.transition_ids[nTransition])];
			if (transition && transition.lanes.length > 0)
			{
				var strFirstLane = GetValue(transition,'lanes',0);
				// Prefer the first outgoing role. A terminal state can inherit its incoming role.
				stateNode.lane = stateNode.lane || strFirstLane;
				transition.target.incoming_lane = transition.target.incoming_lane || strFirstLane;
			}
		}
	}

	var strEdges = '';
	for (var nState = 0; nState < aOrderedStates.length; nState++)
	{
		var stateNode = aOrderedStates[nState];
		var lane = stateNode.lane || stateNode.incoming_lane;
		if (!lane)
		{
			return false;
		}
		if (nState == 0)
		{
			aLanes.splice(aLanes.indexOf(lane),1);
			aLanes.unshift(lane);
		}
		lane.nodes += '    ' + stateNode.id + '[' + stateNode.label + ']\n';

		var aSeenTransitionIds = [];
		for (var nTransition = 0; nTransition < stateNode.transition_ids.length; nTransition++)
		{
			var strTransitionId = GetStringValue(stateNode.transition_ids[nTransition]);
			var transition = mapTransitions['id_' + strTransitionId];
			if (!transition || ArrayValueExists(aSeenTransitionIds,strTransitionId) == true)
			{
				continue;
			}
			aSeenTransitionIds.push(strTransitionId);

			var strLabel = transition.label;
			var aRoleNames = [];
			for (var nRole = 0; nRole < transition.lanes.length; nRole++)
			{
				aRoleNames.push(transition.lanes[nRole].name);
			}
			var strFirstLane = GetValue(transition,'lanes',0);
			if (aRoleNames.length > 1 || (aRoleNames.length == 1 && strFirstLane != lane))
			{
				strLabel += ' (' + aRoleNames.join(', ') + ')';
			}
			var strEdgeId = GetMermaidId(transition.id,'transition_');
			strEdges += '  ' + stateNode.id + ' ' + strEdgeId + '@-->|' + GetMermaidLabel(strLabel,strTransitionId) + '| ' + transition.target.id + '\n';
		}
	}

	var strCode = 'swimlane-beta ' + strDirection + '\n';
	for (var nLane = 0; nLane < aLanes.length; nLane++)
	{
		var lane = aLanes[nLane];
		if (lane.nodes != '')
		{
			strCode += '  subgraph ' + lane.id + ' [' + GetMermaidLabel(lane.name,lane.id) + ']\n' + lane.nodes + '  end\n';
		}
	}
	return strCode + strEdges;
}
